        n = len(sigma)
        stack = [(0, [])]
        decisions = 0
        while stack:
            i, assignment = stack.pop()
            if i == n:
                return math.log2(decisions)
            if assignment[i] is None:
                assignment[i] = 0
                stack.append((i + 1, assignment[:]))
                assignment[i] = 1
                stack.append((i + 1, assignment[:]))
            else:
                decisions += 1
        return math.log2(decisions)

    def generate_instance(n):
